async function returnAuditRevision(pool, schema, user, auditId, note) { return inTransaction(pool, async db => { const audit = await scope(db, schema, user, auditId, true); const role = upper(user.Role); const allowed = (role === 'AUDITI' || (role === 'PIMPINAN' && (await all(db, schema, 'MASTER_PIMPINAN')).some(p => truthy(p.Active) && clean(p.PimpinanID) === clean(user.RefID) && upper(p.Level) === upper(audit.AuditiType) && clean(p.AccessID || p.UnitID) === clean(audit.AuditiID)))) && upper(audit.Status) === 'MENUNGGU ACC AUDITI' || await lead(db, schema, user, auditId) && upper(audit.Status) === 'MENUNGGU ACC LEAD' || role === 'ADMIN_BPM' && upper(audit.Status) === 'MENUNGGU ACC BPM'; if (!allowed) throw new Error('Tidak dapat mengembalikan audit pada tahap ini.'); await removeWhere(db, schema, 'APPROVAL', 'AuditID', auditId); await update(db, schema, 'AMI_AUDITI', 'AuditID', auditId, {Status:'PERLU REVISI AUDITOR'}); return {ok:true}; }); }
async function submitSelfEvaluation(pool, schema, user, auditId) { requireRole(user, ['AUDITI']); return inTransaction(pool, async db => { const audit = await scope(db, schema, user, auditId, true); editableStatus(audit.Status, ['PENUGASAN DITERBITKAN', 'EVALUASI DIRI BERJALAN', 'PERLU REVISI AUDITI']); const assigns = await assignments(db, schema, auditId); if (!assigns.length) throw new Error('Belum ada standar yang ditugaskan.'); const self = await rowsFor(db, schema, 'SELF_EVAL', auditId); for (const a of assigns) { const row = self.find(item => clean(item.AssignID) === clean(a.AssignID)) || {}; if (!clean(row.Capaian) || !clean(row.EvaluasiDiri)) throw new Error(`${a.ItemCode || a.AssignID}: Evaluasi Diri belum lengkap.`); } for (const row of self) await update(db, schema, 'SELF_EVAL', 'SelfEvalID', row.SelfEvalID, {Status:'SUBMITTED', SubmittedAt:now(), SubmittedBy:user.Nama}); await update(db, schema, 'AMI_AUDITI', 'AuditID', auditId, {Status:'EVALUASI DIRI DIKIRIM'}); return {ok:true}; }); }
