async function submitAuditResult(pool, schema, user, auditId) { requireRole(user, ['AUDITOR']); return inTransaction(pool, async db => { const audit = await scope(db, schema, user, auditId, true); editableStatus(audit.Status, ['SIAP VISITASI', 'VISITASI BERJALAN', 'HASIL AUDIT DIISI', 'PERLU REVISI AUDITOR']); if (!(await lead(db, schema, user, auditId))) throw new Error('Hanya Lead Auditor yang dapat mengirim hasil audit.'); const check = await validateAudit(db, schema, auditId); if (!check.ok) throw new Error(`Hasil Audit belum lengkap. ${check.errors.slice(0, 10).join(' | ')}`); const visit = await one(db, schema, 'VISIT', 'AuditID', auditId); if (!visit || !clean(visit.Tanggal) || !clean(visit.Lokasi) || !clean(visit.WakilAuditi)) throw new Error('Data visitasi belum lengkap.'); await update(db, schema, 'AMI_AUDITI', 'AuditID', auditId, {Status:'MENUNGGU ACC AUDITI'}); return {ok:true}; }); }

